/* Raster exports are generated locally; no measurements are sent to a service. */
function imageExportSpec(target){
 const scope=`Project: ${$('projectFilter').value||'All projects'} · Recording: ${$('recordingFilter').selectedOptions[0]?.textContent||'All recordings'} · Site/collar: ${$('siteFilter').value||'All sites / collars'}`;
 if(target==='chart'){const mode=$('chartView').value,single=mode==='single';return{element:$('chart'),title:single?'Chamber concentration':'Site flux over time',gas,scope:scope+(single&&current()?' · Reading: '+current().id:''),subtitle:$('chartSub').textContent,legend:$('chartLegend').textContent,notes:$('chartNote').textContent,filename:single?'concentration':'flux-time-series'}}
 if(target==='fluxOverview')return{element:$('fluxOverview'),title:'Campaign flux summary',gas:$('overviewGas').value,scope,subtitle:$('overviewGas').selectedOptions[0]?.textContent||'',legend:'Orange = emission · Teal = uptake',notes:$('overviewNote').textContent,filename:'campaign-flux'};
 if(target==='heatCanvas')return{element:$('heatCanvas'),title:$('heatRenderMode').value==='points'?'Spatial flux · measured points':'Flux heatmap',gas:$('mapGas').value,scope,subtitle:`${$('mapGas').selectedOptions[0]?.textContent||''} · ${$('heatDirection').selectedOptions[0]?.textContent||''} · ${$('heatGrouping').selectedOptions[0]?.textContent||''} · ${$('heatTimeFrom').value||'start'} → ${$('heatTimeTo').value||'end'} · radius ${$('heatRadius').value} m`,legend:`Lower magnitude → higher magnitude: ${$('heatMax').textContent}. ${$('heatPoints').checked?'Flux markers shown.':'Markers hidden.'} ${$('heatUncertainty').checked?'Dashed GPS uncertainty rings shown.':'GPS uncertainty rings hidden.'}`,notes:$('mapNote').textContent,filename:'flux-heatmap',heat:true};
 throw Error('Unknown visualization.');
}
function wrapImageText(ctx,text,width){const lines=[];for(const paragraph of String(text||'').split(/\n/)){let line='';for(const word of paragraph.trim().split(/\s+/)){if(ctx.measureText(line?line+' '+word:word).width>width&&line){lines.push(line);line=word}else line=line?line+' '+word:word}if(line)lines.push(line)}return lines}
async function rasterSource(element){
 if(element.tagName.toLowerCase()==='canvas')return{image:element,width:element.width,height:element.height};
 const clone=element.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');const box=(element.getAttribute('viewBox')||'').split(/[ ,]+/).map(Number),width=box.length===4&&box[2]>0?box[2]:Number(element.getAttribute('width'))||900,height=box.length===4&&box[3]>0?box[3]:Number(element.getAttribute('height'))||300;clone.setAttribute('width',width);clone.setAttribute('height',height);clone.setAttribute('font-family','Arial, sans-serif');
 const url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(clone)],{type:'image/svg+xml;charset=utf-8'}));try{const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Could not render this chart for export.'));img.src=url});return{image,width,height}}finally{URL.revokeObjectURL(url)}
}
async function exportVisualization(target,format,button){const original=button.textContent;button.disabled=true;button.textContent='Preparing…';try{
 if(document.fonts?.ready)await document.fonts.ready;const spec=imageExportSpec(target),source=await rasterSource(spec.element);if(!source.width||!source.height)throw Error('This visualization is not ready yet.');
 const width=Math.max(1200,Math.min(4000,source.width+96)),margin=48,contentWidth=width-2*margin,canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');if(!ctx)throw Error('Image export is unavailable in this browser.');
 const textLines=(text,font)=>{ctx.font=font;return wrapImageText(ctx,text,contentWidth)},scope=textLines(spec.scope,'16px Arial'),sub=textLines(spec.subtitle,'16px Arial'),legend=textLines(spec.legend,'16px Arial'),notes=textLines(spec.notes,'14px Arial'),plotHeight=Math.round(contentWidth*source.height/source.width),header=110+(scope.length+sub.length)*24,footer=50+legend.length*24+notes.length*20+(spec.heat?30:0),logicalHeight=header+plotHeight+footer,scale=Math.min(2,Math.sqrt(24000000/(width*logicalHeight)));canvas.width=Math.ceil(width*scale);canvas.height=Math.ceil(logicalHeight*scale);ctx.scale(scale,scale);ctx.fillStyle='#F7F9FC';ctx.fillRect(0,0,width,logicalHeight);ctx.fillStyle='#172033';ctx.font='bold 28px Arial';ctx.fillText('Fieldflux · '+spec.title,margin,48);ctx.fillStyle='#217A8A';ctx.font='16px Arial';let y=80;for(const line of [...scope,...sub]){ctx.fillText(line,margin,y);y+=24}ctx.drawImage(source.image,margin,header,contentWidth,plotHeight);y=header+plotHeight+24;
 if(spec.heat){const gradient=ctx.createLinearGradient(margin,0,margin+220,0);gradient.addColorStop(0,'#F7F9FC');gradient.addColorStop(1,$('heatDirection').value==='uptake'?'#217A8A':'#C06131');ctx.fillStyle=gradient;ctx.fillRect(margin,y,220,12);y+=30}
 ctx.fillStyle='#217A8A';ctx.font='16px Arial';for(const line of legend){ctx.fillText(line,margin,y);y+=24}y+=10;ctx.font='14px Arial';for(const line of notes){ctx.fillText(line,margin,y);y+=20}
 const mime=format==='jpg'?'image/jpeg':'image/png',blob=await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('Image encoding failed.')),mime,.95));const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`fieldflux-${spec.filename}-${spec.gas}.${format}`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);$('imageExportStatus').textContent=`${format.toUpperCase()} download prepared for ${spec.title}.`;
 }catch(error){$('imageExportStatus').textContent='Export failed: '+error.message}finally{button.disabled=false;button.textContent=original}}
document.querySelectorAll('[data-image-target]').forEach(button=>button.onclick=()=>exportVisualization(button.dataset.imageTarget,button.dataset.imageFormat,button));
